```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Government Dashboard</title>
    <!-- Inline CSS Styles -->
    <style>
        /* General Page Styles */
        body {
            font-family: Arial, sans-serif;
            margin: 0;
            padding: 0;
            background-color: #f4f4f4;
        }

        /* Header Section */
        header {
            background-color: #2f2f2f;
            color: white;
            padding: 10px 0;
            text-align: center;
            font-size: 1.8rem;
        }

        /* Sidebar Styles */
        .sidebar {
            position: fixed;
            top: 0;
            left: 0;
            width: 250px;
            height: 100%;
            background-color: #333;
            padding-top: 20px;
            padding-left: 15px;
        }

        .sidebar .title {
            font-size: 1.6rem;
            color: white;
            margin-bottom: 30px;
            font-weight: bold;
        }

        .sidebar a {
            display: block;
            padding: 10px;
            color: white;
            text-decoration: none;
            font-size: 1.2rem;
            margin-bottom: 10px;
            border-radius: 5px;
            transition: background-color 0.3s ease;
        }

        .sidebar a:hover {
            background-color: #575757;
        }

        /* Main Content Section */
        .main-content {
            margin-left: 270px;
            padding: 20px;
        }

        .main-content .box {
            background-color: #ffffff;
            padding: 20px;
            border-radius: 8px;
            box-shadow: 0px 4px 8px rgba(0, 0, 0, 0.1);
        }

        .main-content .box h2 {
            font-size: 2rem;
            margin-bottom: 20px;
        }

        .main-content .stats {
            background-color: #f8f8f8;
            padding: 20px;
            margin-top: 20px;
            border-radius: 8px;
        }

        .main-content .stats h3 {
            font-size: 1.5rem;
            margin-bottom: 10px;
        }

        .main-content .stats ul {
            list-style-type: none;
            padding-left: 0;
        }

        .main-content .stats ul li {
            font-size: 1.1rem;
            margin-bottom: 10px;
        }

        /* Footer Styles */
        footer {
            background-color: #2f2f2f;
            color: white;
            padding: 10px;
            text-align: center;
            position: fixed;
            bottom: 0;
            width: 100%;
        }
    </style>
</head>
